const { db } = require('../db');

exports.handler = async (event) => {
  // Freshly resolve authorizer claims per invocation
  const authorizerContext = event.requestContext?.authorizer;
  if (!authorizerContext?.userId) {
    return { statusCode: 401, body: JSON.stringify({ error: 'Unauthorized' }) };
  }

  const accountId = event.pathParameters?.accountId;

  const account = await db.query(
    'SELECT id FROM bank_accounts WHERE id = $1 AND user_id = $2',
    [accountId, authorizerContext.userId]
  );
  if (!account.rows.length) {
    return { statusCode: 403, body: JSON.stringify({ error: 'Forbidden: access denied to account' }) };
  }

  const transactions = await db.query(
    'SELECT * FROM bank_transactions WHERE account_id = $1',
    [accountId]
  );

  return {
    statusCode: 200,
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ accountId, transactions: transactions.rows }),
  };
};
